"""Idempotent documentation-only links for the supplied calendar."""
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def append(path, text):
    p=ROOT/path; old=p.read_text(encoding='utf-8-sig')
    if text.strip() not in old: p.write_text(old.rstrip()+'\n\n'+text.strip()+'\n',encoding='utf-8')
def replace(path, before, after):
    p=ROOT/path; old=p.read_text(encoding='utf-8-sig')
    if before in old: p.write_text(old.replace(before,after),encoding='utf-8')
    elif after not in old: raise RuntimeError('Anchor not found: '+path)

